TF.KOREA_ANGLE = 2.4958;   // 한국(127°E) 방향의 화면 각
TF.northEarth = (ctx, cx, cy, R, rot = 0, opt = {}) => {
  ctx.save();
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, 2*Math.PI);
  const g = ctx.createRadialGradient(cx - R*0.3, cy - R*0.3, R*0.1, cx, cy, R);
  g.addColorStop(0, '#4dabf7'); g.addColorStop(1, '#1864ab');
  ctx.fillStyle = g; ctx.fill(); ctx.clip();
  ctx.translate(cx, cy); ctx.rotate(rot - (opt.alignKorea ? TF.KOREA_ANGLE : 0)); ctx.scale(R, R);
  if (!TF._land) TF._land = new Path2D(TF.NORTH_LAND);
  ctx.fillStyle = '#8f7a55'; ctx.fill(TF._land);
  ctx.lineWidth = 1.2/R; ctx.strokeStyle = 'rgba(40,30,20,.5)'; ctx.stroke(TF._land);
  // 위도선 30°, 60° 와 북극 얼음
  ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = 1/R; ctx.setLineDash([3/R, 4/R]);
  for (const la of [30, 60]){ ctx.beginPath(); ctx.arc(0, 0, Math.cos(la*Math.PI/180), 0, 2*Math.PI); ctx.stroke(); }
  ctx.setLineDash([]);
  ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.beginPath(); ctx.arc(0, 0, Math.cos(83*Math.PI/180), 0, 2*Math.PI); ctx.fill();
  ctx.restore();
  ctx.save(); ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(cx, cy, R, 0, 2*Math.PI); ctx.stroke(); ctx.restore();
};
